I’ll proceed with drafting a React functional component that:

- Polls a mock API endpoint every 5 seconds (within the ≤5.25s refresh rate constraint).
- Uses `useEffect` and `setTimeout` for polling control (to avoid overlapping calls).
- Simulates API response with a mock promise resolving in ~100ms (under the 125ms API response constraint).
- Captures performance timings from fetch start to render completion using the browser Performance API.
- Logs or reports the measured refresh duration for monitoring.
- Renders simple placeholder dashboard data.

I’ll share a concise React code snippet below for early validation and iteration. Please review and provide any initial feedback or additional data points needed for your backend API schema.

---

```jsx
import React, { useState, useEffect, useRef } from 'react';

const MOCK_API_DELAY_MS = 100; // Simulated API response time <=125ms
const POLL_INTERVAL_MS = 5000; // Poll every 5 seconds (within 5.25s limit)

function mockFetchDashboardData() {
  return new Promise((resolve) => {
    setTimeout(() => {
      // Mock dashboard data structure
      resolve({
        timestamp: new Date().toISOString(),
        metrics: {
          activeUsers: Math.floor(Math.random() * 1000),
          errorsLastMinute: Math.floor(Math.random() * 20),
          cpuLoad: (Math.random() * 100).toFixed(1),
        },
      });
    }, MOCK_API_DELAY_MS);
  });
}

export default function Dashboard() {
  const [data, setData] = useState(null);
  const [refreshDuration, setRefreshDuration] = useState(null);
  const pollingTimeout = useRef(null);

  useEffect(() => {
    let isMounted = true;

    async function fetchData() {
      // Mark fetch start time
      const fetchStart = performance.now();

      try {
        const response = await mockFetchDashboardData();

        if (isMounted) {
          setData(response);

          // Mark render completion time after state update and paint
          // Use requestAnimationFrame twice to ensure paint is done
          requestAnimationFrame(() => {
            requestAnimationFrame(() => {
              const fetchEnd = performance.now();
              const durationMs = fetchEnd - fetchStart;
              setRefreshDuration(durationMs.toFixed(1));

              // TODO: Replace with real telemetry/reporting hook
              console.log(`[Performance] Refresh took ${durationMs.toFixed(1)} ms`);
            });
          });
        }
      } catch (error) {
        console.error('Error fetching dashboard data:', error);
      } finally {
        if (isMounted) {
          pollingTimeout.current = setTimeout(fetchData, POLL_INTERVAL_MS);
        }
      }
    }

    fetchData();

    return () => {
      isMounted = false;
      if (pollingTimeout.current) clearTimeout(pollingTimeout.current);
    };
  }, []);

  return (
    <div style={{ fontFamily: 'Arial, sans-serif', padding: 20 }}>
      <h2>Dashboard (Refresh interval: {POLL_INTERVAL_MS / 1000}s)</h2>
      {data ? (
        <>
          <p>Last updated: {new Date(data.timestamp).toLocaleTimeString()}</p>
          <ul>
            <li>Active Users: {data.metrics.activeUsers}</li>
            <li>Errors (last minute): {data.metrics.errorsLastMinute}</li>
            <li>CPU Load: {data.metrics.cpuLoad}%</li>
          </ul>
          <p style={{ fontSize: 12, color: '#666' }}>
            Fetch-to-render duration: {refreshDuration} ms
          </p>
        </>
      ) : (
        <p>Loading dashboard data...</p>
      )}
    </div>
  );
}
```

